using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt(Name = "summarize"), Description("Generates a prompt to summarize the provided text.")]
    public static IEnumerable<PromptMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        yield return new PromptMessage
        {
            Role = Role.User,
            Content = new TextContentBlock { Text = $"Please summarize the following text in a {style} style.\n\nText:\n{text}" }
        };
    }
}

